1	// `andesim run --mode fast|cycle|hybrid [engine selection] ELF [-- engine args]`.
2	//
3	// The top selection axis. F7/F8 land the two standalone models, `fast` (QEMU)
4	// and `cycle` (a cycle-accurate engine, from reset): each resolves its
5	// engine, then hands off to transparent passthrough -- the ELF plus everything
6	// after `--` becomes the engine's own command line, run with inherited stdio,
7	// no timeout, and the exit code propagated, so a gdbstub / monitor /
8	// semihosting console all behave as if the engine were invoked directly.
9	// `hybrid` (F9) orchestrates a QEMU1 -> vsim handoff via run_plan and prints the
10	// window-cycle figure (the vsim mcycle delta).
11	#include <algorithm>
12	#include <chrono>
13	#include <cstdint>
14	#include <cstdio>
15	#include <cstdlib>
16	#include <filesystem>
17	#include <optional>
18	#include <string>
19	#include <string_view>
20	#include <thread>
21	#include <vector>
22	
23	#include "argv.hpp"
24	#include "cli.hpp"
25	#include "elf_syms.hpp"
26	#include "engine_descriptor.hpp"
27	#include "engine_registry.hpp"
28	#include "hybrid.hpp"
29	#include "hybrid/state_abi.h"  // HYBRID_V_SCRATCH_BYTES (L26/F3 overlap check)
30	#include "models.hpp"
31	#include "plan.hpp"
32	#include "process.hpp"
33	#include "repo_root.hpp"
34	#include "run_passthrough.hpp"
35	#include "run_plan.hpp"
36	#include "shm.hpp"
37	#include "state.hpp"
38	#include "state_diff.hpp"
39	#include "vsim_filter.hpp"
40	
41	namespace fs = std::filesystem;
42	
43	namespace andes_sim {
44	namespace {
45	
46	// Resolve `path` to an absolute, EXISTING ELF. Returns the resolved string on
47	// success; on failure prints an error tagged with `ctx` and returns "". The
48	// existence check is here, at the one resolver fast/cycle/cycle-gdb share, so a
49	// missing path fails with a clear "ELF not found" instead of being handed to the
50	// engine (e.g. qemu's cryptic "Unable to find the RISC-V BIOS"). Mirrors the
51	// up-front check run_hybrid already does.
52	std::string abs_elf(const std::string& path, const std::string& ctx) {
53	  std::error_code ec;
54	  fs::path abs = fs::absolute(path, ec);
55	  if (ec) {
56	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
57	                 ctx.c_str(), path.c_str());
58	    return "";
59	  }
60	  if (!fs::is_regular_file(abs, ec)) {
61	    std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
62	                 path.c_str());
63	    return "";
64	  }
65	  return abs.string();
66	}
67	
68	// Validate the lone-ELF positional shape the standalone models require: print
69	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
70	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
71	// spawns a --describe subprocess per Verilator build). `model` labels the error.
72	int check_one_elf(const Cli& cli, const char* model) {
73	  if (cli.positional.empty()) {
74	    std::fprintf(stderr,
75	                 "andesim run --mode %s: missing ELF (the workload to run; "
76	                 "e.g. a tests/fixtures/<name>.elf)\n",
77	                 model);
78	    return 2;
79	  }
80	  if (cli.positional.size() > 1) {
81	    std::fprintf(stderr,
82	                 "andesim run --mode %s: unexpected argument '%s' "
83	                 "(engine args go after --)\n",
84	                 model, cli.positional[1].c_str());
85	    return 2;
86	  }
87	  return 0;
88	}
89	
90	// Reject an ELF whose class width (rv32/rv64) does not match the engine it would
91	// run on -- a clear pre-flight error instead of a cryptic "not of ELFCLASSxx"
92	// from deep inside the engine. Both directions. Returns "" when they agree, when
93	// the ELF is unreadable/not-ELF (reported elsewhere), or when the engine
94	// declares no xlen (cannot judge). Shared by cycle and hybrid: one wording.
95	std::string elf_engine_arch_error(const std::string& elf,
96	                                  const EngineDescriptor& eng) {
97	  const int ex = elf_xlen(elf);
98	  if (ex == 0 || eng.xlen == 0 || ex == eng.xlen) return "";
99	  char buf[256];
100	  std::snprintf(buf, sizeof(buf),
101	                "ELF is rv%d but engine '%s' is rv%ld -- pick a matching engine "
102	                "or an rv%d ELF",
103	                ex, eng.id.c_str(), eng.xlen, ex);
104	  return buf;
105	}
106	
107	// Print the dry-run preview: the exact command(s) andesim WOULD spawn, each
108	// shell-quoted and labeled, executing nothing. Shared by every --mode so the
109	// preview format is identical; `labels[i]` annotates `argvs[i]` (e.g.
110	// "fast-leg [qemu64]", "standalone [qemu64]"). Always returns 0 -- a dry run
111	// reports the plan, it does not run it.
112	int print_dry_run(const std::vector<std::vector<std::string>>& argvs,
113	                  const std::vector<std::string>& labels) {
114	  std::printf("[andesim] dry-run: %zu command(s), not executed\n", argvs.size());
115	  for (size_t i = 0; i < argvs.size(); ++i) {
116	    std::printf("# command %zu/%zu: %s\n", i + 1, argvs.size(),
117	                labels[i].c_str());
118	    std::printf("%s\n", render_argv(argvs[i]).c_str());
119	  }
120	  return 0;
121	}
122	
123	// `run --mode cycle` presentation: spawn the engine, hiding its startup banner
124	// and verbose [info] log (VsimFilter), relaying only the program's own output
125	// and any real diagnostics, then restate the lifted cycle count as andesim's own
126	// one-line result under the [andesim] prefix. The count is printed AFTER the run
127	// (the engine logs it at exit), so it follows the program output. Returns the
128	// engine exit code. Unlike fast's exec_passthrough, the parent stays alive to
129	// filter -- fine, because cycle (without --gdb) is a batch run, not interactive.
130	int run_cycle_clean(const std::vector<std::string>& argv) {
131	  VsimFilter filter;
132	  const int rc = run_line_filtered(
133	      argv, [&filter](int stream, std::string_view line) {
134	        std::FILE* dst = nullptr;
135	        switch (filter.classify(stream, line)) {
136	          case VsimFilter::Dest::kStdout: dst = stdout; break;
137	          case VsimFilter::Dest::kStderr: dst = stderr; break;
138	          case VsimFilter::Dest::kDrop: return;
139	        }
140	        std::fwrite(line.data(), 1, line.size(), dst);
141	        std::fputc('\n', dst);
142	      });
143	  if (const std::optional<uint64_t> c = filter.cycles())
144	    std::printf("[andesim] %llu cycles\n", static_cast<unsigned long long>(*c));
145	  return rc;
146	}
147	
148	// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
149	// then run the resolved engine standalone with `extra` (model flags the
150	// framework forwards, e.g. fast's -m) followed by the post-`--` args verbatim.
151	// `clean_output` picks how the engine's output is presented: fast inherits the
152	// stdio transparently (exec_passthrough -- an interactive gdbstub / monitor /
153	// semihosting console works unchanged); cycle filters out the engine's banner +
154	// [info] noise and restates the cycle count (run_cycle_clean). Either way the
155	// exit code propagates. The per-model engine + selection are resolved by the
156	// caller; `model` here only labels the positional diagnostics.
157	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
158	                   const char* model, const std::vector<std::string>& extra = {},
159	                   bool clean_output = false) {
160	  if (int rc = check_one_elf(cli, model)) return rc;
161	  // QEMU's -bios flag searches its data directory for relative paths rather
162	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
163	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
164	  if (elf.empty()) return 2;
165	  std::vector<std::string> args = extra;
166	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
167	  std::string err;
168	  const std::vector<std::string> argv =
169	      passthrough_argv(eng, "standalone", elf, args, err);
170	  if (!err.empty()) {
171	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
172	    return 2;
173	  }
174	  // --dry-run: print the exact engine command and stop, spawning nothing -- the
175	  // full qemu/vsim command (incl. -bios <elf> and any post-`--`).
176	  if (cli.dry_run)
177	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
178	  return clean_output ? run_cycle_clean(argv) : exec_passthrough(argv);
179	}
180	
181	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
182	// only the built-in qemu descriptor, so it resolves that directly rather than
183	// discover_engines(), which would spawn a --describe subprocess per Verilator
184	// build only to discard them all here.
185	int run_fast(const Cli& cli) {
186	  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
187	  if (!cli.engine.empty() && cli.engine != kQemuId64 && cli.engine != kQemuId32) {
188	    std::fprintf(stderr,
189	                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
190	                 "got '%s'\n",
191	                 cli.engine.c_str());
192	    return 2;
193	  }
194	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
195	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
196	  std::string err;
197	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
198	  if (!err.empty()) {
199	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
200	    return 2;
201	  }
202	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
203	  if (cli.gdb) {
204	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
205	    extra.push_back("-gdb");
206	    extra.push_back("tcp::" + port);
207	    extra.push_back("-S");
208	  }
209	  // Pick rv32 vs rv64. An explicit --engine (qemu32/qemu64) wins; otherwise read
210	  // the ELF's class so an rv32 program lands on qemu-system-riscv32 instead of
211	  // the rv64 default. Warn (do not fail) if an explicit choice contradicts the
212	  // ELF -- the override is the user's call.
213	  const int elf_w = cli.positional.empty() ? 0 : elf_xlen(cli.positional[0]);
214	  int xlen;
215	  if (cli.engine == kQemuId32) xlen = 32;
216	  else if (cli.engine == kQemuId64) xlen = 64;
217	  else xlen = elf_w ? elf_w : 64;  // no explicit engine: follow the ELF (else rv64)
218	  // Only an explicit engine can disagree with the ELF (when none is given, xlen
219	  // == elf_w), so this guard already implies an explicit --engine.
220	  if (elf_w && elf_w != xlen)
221	    std::fprintf(stderr,
222	                 "[andesim] --mode fast: --engine %s is rv%d but the ELF is rv%d "
223	                 "(running as rv%d)\n",
224	                 cli.engine.c_str(), xlen, elf_w, xlen);
225	  return run_standalone(cli, builtin_qemu_arch(xlen), "fast", extra);
226	}
227	
228	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
229	// its --jtag-port only after it has reset and halted the hart, so the debugger we
230	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
231	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
232	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
233	// single debugger slot). Returns false on timeout.
234	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
235	  constexpr int kPollMs = 50;
236	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
237	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
238	      char line[512];
239	      while (std::fgets(line, sizeof line, f)) {
240	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
241	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
242	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
243	        unsigned lport = 0, st = 0;
244	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
245	            && st == 0x0A && lport == port) {
246	          std::fclose(f);
247	          return true;
248	        }
249	      }
250	      std::fclose(f);
251	    }
252	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
253	  }
254	  return false;
255	}
256	
257	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
258	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
259	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
260	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
261	  const char* iceman = std::getenv("ICEMAN");
262	  if (!iceman || !*iceman) {
263	    std::fprintf(stderr,
264	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
265	                 "(export ICEMAN=<path to ICEman binary>)\n");
266	    return 2;
267	  }
268	  // Build vsim argv from the standalone template, appending user passthrough
269	  // and the JTAG port flag.
270	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
271	  if (elf.empty()) return 2;
272	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
273	  std::vector<std::string> vsim_pass = cli.passthrough;
274	  vsim_pass.push_back("--jtag-port");
275	  vsim_pass.push_back(jtag_port);
276	  std::string err;
277	  const std::vector<std::string> vsim_argv =
278	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
279	  if (!err.empty()) {
280	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
281	    return 2;
282	  }
283	  std::fprintf(stderr,
284	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
285	               jtag_port.c_str());
286	  if (fork_background(vsim_argv) < 0) {
287	    std::fprintf(stderr,
288	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
289	    return 1;
290	  }
291	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
292	  // Wait for the port to be LISTENing before launching the debugger (it does not
293	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
294	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
295	  // but launch anyway if it never appears.
296	  if (const int pnum = std::atoi(jtag_port.c_str());
297	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
298	    std::fprintf(stderr,
299	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
300	                 "after 20s; launching the debugger anyway\n",
301	                 jtag_port.c_str());
302	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
303	  // localhost, port 9104) instead of its default real-hardware adapter; without
304	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
305	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
306	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
307	}
308	
309	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
310	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
311	// engine's own output. Unlike fast, this must discover the Verilator build(s)
312	// to resolve the engine (explicit --engine, else the sole one).
313	int run_accurate(const Cli& cli) {
314	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
315	  // --describe subprocess per Verilator build only to fail on the argument.
316	  if (int rc = check_one_elf(cli, "cycle")) return rc;
317	  // --mem-size is validated but has nothing to size: the cycle engine always
318	  // models its full DRAM window. Say so instead of silently ignoring it.
319	  if (!cli.mem_size.empty()) {
320	    std::string se;
321	    if (parse_size(cli.mem_size, se); !se.empty()) {
322	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
323	                   se.c_str());
324	      return 2;
325	    }
326	    std::fprintf(stderr,
327	                 "[andesim] --mem-size: the cycle engine models its full "
328	                 "DRAM window; nothing to size\n");
329	  }
330	  Discovery disc = discover_engines();
331	  std::string err;
332	  const EngineDescriptor* eng =
333	      resolve_accurate_engine(disc.engines, cli.engine, err);
334	  if (!eng) {
335	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
336	    // Surface why an expected engine may be absent (failed --describe, etc.).
337	    for (const std::string& w : disc.warnings)
338	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
339	    return 2;
340	  }
341	  // The ELF must match the engine's width: an rv32 ELF on an rv64 engine (or
342	  // vice versa) cannot run. Catch it here with a clear message instead of the
343	  // engine's cryptic "not of ELFCLASSxx". check_one_elf above guaranteed a lone
344	  // positional.
345	  if (std::string e = elf_engine_arch_error(cli.positional[0], *eng); !e.empty()) {
346	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", e.c_str());
347	    return 2;
348	  }
349	  // --dry-run previews the standalone command and spawns nothing, so it takes
350	  // precedence over the interactive --gdb path (a dry run launches no debugger).
351	  if (cli.gdb && !cli.dry_run) return run_cycle_gdb(cli, *eng);
352	  // clean_output: hide vsim's banner + [info] log, restate the cycle count under
353	  // [andesim] (fast keeps raw passthrough -- QEMU has no such banner and its
354	  // monitor/gdbstub are interactive).
355	  return run_standalone(cli, *eng, "cycle", /*extra=*/{}, /*clean_output=*/true);
356	}
357	
358	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
359	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle
360	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
361	// driver's tests/e2e.sh delegation with a single window-cycle line.
362	int run_hybrid(const Cli& cli) {
363	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
364	  auto fail = [](const std::string& msg) {
365	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
366	    return 2;
367	  };
368	
369	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
370	
371	  // Resolve to an absolute, existing ELF through the shared resolver -- the same
372	  // check and "ELF not found" message fast/cycle get (abs_elf already printed on
373	  // failure). pc-trigger resolution below then reads the ELF's .symtab.
374	  const std::string elf_path = abs_elf(cli.positional[0], "--mode hybrid");
375	  if (elf_path.empty()) return 2;
376	  const fs::path elf{elf_path};  // for .stem() in the banner / PASS lines
377	
378	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
379	  // mistake fails fast without spawning a --describe per Verilator build.
380	  std::string err;
381	  const Trigger trig = hybrid_trigger(cli, elf_path, err);
382	  if (!err.empty()) return fail(err);
383	
384	  // hybrid_trigger has already guaranteed trig.kind is marker|pc (the only
385	  // hybrid triggers; unknown returned an error above) -- exactly the entry
386	  // boundary --verify needs the oracle to arm on.
387	  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
388	  if (!err.empty()) return fail(err);
389	
390	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
391	  if (!cli.mem_size.empty()) {
392	    std::string se;
393	    mem = parse_size(cli.mem_size, se);
394	    if (!se.empty()) return fail("--mem-size: " + se);
395	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
396	    // guest RAM here. The physical mmap reserves one V-scratch page above the
397	    // program's RAM (L26/F2), so the usable --mem-size is 2 GiB minus that
398	    // page. Failing now beats allocating a huge mmap file first and letting
399	    // QEMU die late.
400	    if (mem > max_program_mem_bytes())
401	      return fail("--mem-size " + cli.mem_size +
402	                  " exceeds the AE350 DRAM window (2G minus the V-scratch "
403	                  "reservation)");
404	  }
405	
406	  // L26/F3: refuse a run whose static image would extend into the reserved
407	  // V-transport scratch page. Scheme D parks the scratch in the TOP page of the
408	  // physical mmap; a PT_LOAD segment reaching there means the ELF was linked for
409	  // more RAM than --mem-size grants, and QEMU would load it straight onto the
410	  // scratch -> silent corruption. Derive the page's start from
411	  // physical_mmap_bytes (the same sizing the mmap uses) rather than a bare
412	  // `mem`, so the threshold tracks the reservation shape instead of relying on
413	  // the +page/-page adjustments cancelling. ram_base is the fixed andes_ae350
414	  // DRAM base (0; see L10). Skipped when the ELF cannot be read -- downstream
415	  // reports it.
416	  {
417	    std::string e;
418	    const uint64_t top = elf_load_top(elf_path, e);
419	    const uint64_t scratch_gpa =
420	        static_cast<uint64_t>(physical_mmap_bytes(mem)) - HYBRID_V_SCRATCH_BYTES;
421	    if (e.empty() && top > scratch_gpa) {
422	      char msg[256];
423	      std::snprintf(msg, sizeof(msg),
424	                    "ELF static image ends at 0x%llx, overlapping the reserved "
425	                    "V-transport scratch page at 0x%llx (ram_base + --mem-size)"
426	                    "; raise --mem-size or shrink the image",
427	                    static_cast<unsigned long long>(top),
428	                    static_cast<unsigned long long>(scratch_gpa));
429	      return fail(msg);
430	    }
431	  }
432	
433	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
434	  // or the sole cycle-accurate engine (reusing the F8 selector).
435	  Discovery disc = discover_engines();
436	  const EngineDescriptor* acc =
437	      resolve_accurate_engine(disc.engines, cli.engine, err);
438	  if (!acc) {
439	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
440	    for (const std::string& w : disc.warnings)
441	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
442	    return 2;
443	  }
444	
445	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
446	  // cannot share architectural state with the rv64 fast leg).
447	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
448	  // ...and the ELF must match that engine width too (same guard as cycle).
449	  if (std::string e = elf_engine_arch_error(elf_path, *acc); !e.empty())
450	    return fail(e);
451	
452	  Plan plan;
453	  plan.elf = elf_path;
454	  plan.mem_size = mem;
455	  Step qemu_step{kQemuId64, "fast-leg", trig};
456	  Step vsim_step{acc->id, "accurate-leg", trig};
457	  vsim_step.extra_args = std::move(vsim_extras);  // kanata, validated
458	  plan.steps = {qemu_step, vsim_step};
459	
460	  // Banner to stderr so the window-cycle result stands alone on stdout.
461	  // vlen is the synced value the fast leg inherits from the engine.
462	  std::fprintf(stderr,
463	               "[andesim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s\n",
464	               acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
465	               elf.stem().string().c_str());
466	
467	  PlanOptions opts;
468	  opts.dry_run = cli.dry_run;
469	  const PlanResult r = run_plan(plan, disc.engines, opts);
470	  if (!r.ok()) {
471	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
472	    return 1;
473	  }
474	  // --dry-run: print the exact per-leg commands run_plan assembled -- the QEMU
475	  // fast leg (incl. the staged -readconfig from the engine's --print-qemu-config)
476	  // then the vsim accurate leg -- and stop. Nothing was spawned.
477	  if (cli.dry_run) {
478	    std::vector<std::string> labels;
479	    labels.reserve(plan.steps.size());
480	    for (const Step& s : plan.steps)
481	      labels.push_back(s.role + " [" + s.engine_id + "]");
482	    return print_dry_run(r.argvs, labels);
483	  }
484	  // Relay each leg's stdout: the program's own prints (QEMU1 phase-1 output,
485	  // then anything the ROI wrote on vsim) belong to the user. The vsim
486	  // (accurate) leg's output is prefixed by vsim's startup banner (Copyright /
487	  // Version) -- strip it so only real program output shows, the same as `cycle`
488	  // does; its [info] log is already absent (the leg's stderr was dropped at
489	  // capture). The QEMU leg has no banner, so it relays verbatim.
490	  for (size_t i = 0; i < r.phases.size(); ++i) {
491	    const std::string& out = r.phases[i].out;
492	    if (out.empty()) continue;
493	    if (i < plan.steps.size() && plan.steps[i].role == "accurate-leg") {
494	      const std::string shown = strip_vsim_banner(out);
495	      std::fwrite(shown.data(), 1, shown.size(), stdout);
496	    } else {
497	      std::fwrite(out.data(), 1, out.size(), stdout);
498	    }
499	  }
500	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
501	  // vsim mcycle delta.
502	  {
503	    const unsigned long long q_mc = r.phases[0].mcycle;
504	    const unsigned long long v_mc = r.phases[1].mcycle;
505	    std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
506	                trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
507	  }
508	
509	  // --verify (verify_oracle F4, default off): re-run the ELF on pure QEMU
510	  // with the plugin draining at the ROI exit boundary, sampling at vsim's
511	  // halt pc, and diff the two drains in-process. The oracle plan gets its
512	  // own fresh mmap: reusing the main run's would boot the oracle on the
513	  // hybrid run's leftover memory. Its stdout is dropped -- the program's
514	  // output was already relayed from the main run.
515	  if (cli.verify) {
516	    char pcbuf[32];
517	    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
518	                  static_cast<unsigned long long>(r.phases[1].st.pc));
519	    Trigger vtrig;
520	    vtrig.kind = "verify-" + trig.kind;
521	    if (trig.kind == "pc") vtrig.params["exit_pc"] = trig.params.at("exit_pc");
522	    vtrig.params["drain_pc"] = pcbuf;
523	
524	    Plan vplan;
525	    vplan.elf = elf_path;
526	    vplan.mem_size = mem;
527	    vplan.steps = {Step{kQemuId64, "fast-leg", vtrig}};
528	
529	    std::fprintf(stderr,
530	                 "[andesim] verify: oracle leg (pure QEMU drains at the ROI "
531	                 "exit, pc=%s)\n",
532	                 pcbuf);
533	    const PlanResult vr = run_plan(vplan, disc.engines);
534	    if (!vr.ok()) {
535	      std::fprintf(stderr, "andesim run --verify: %s\n", vr.error.c_str());
536	      return 1;
537	    }
538	    // Pass the cycle engine's supported Andes-CSR list so verify skips CSRs the
539	    // engine does not implement (it never restored/re-read them; comparing
540	    // would false-diff). Mirrors the resume/drain gating in vsim.
541	    const DiffReport d =
542	        diff_states(vr.phases[0].st, r.phases[1].st, acc->andes_csrs);
543	    print_diff_report(d);
544	    if (!d.ok()) {
545	      std::fprintf(stderr,
546	                   "andesim run --verify: vsim drain diverges from the "
547	                   "QEMU oracle\n");
548	      return 1;
549	    }
550	    std::printf("[verify] PASS: vsim drain matches the QEMU oracle\n");
551	  }
552	
553	  std::printf("PASS: --mode hybrid --trigger %s (%s)\n", trig.kind.c_str(),
554	              elf.stem().string().c_str());
555	  return 0;
556	}
557	
558	}  // namespace
559	
560	int cmd_run(const Cli& cli) {
561	  if (cli.model.empty()) {
562	    std::fprintf(stderr,
563	                 "andesim run: --mode fast|cycle|hybrid is required "
564	                 "(pick the composition; see 'andesim run --help')\n");
565	    return 2;
566	  }
567	  if (!find_model(cli.model)) {
568	    std::fprintf(stderr,
569	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
570	                 cli.model.c_str());
571	    return 2;
572	  }
573	  if (!cli.gdb_port.empty() && !cli.gdb) {
574	    std::fprintf(stderr, "andesim run: --gdb-port requires --gdb\n");
575	    return 2;
576	  }
577	  // --gdb is an interactive debugging aid; the hybrid handoff runs QEMU1 then
578	  // vsim sequentially in a pipeline and cannot pause for a debugger to attach.
579	  if (cli.gdb && cli.model == "hybrid") {
580	    std::fprintf(stderr,
581	                 "andesim run: --gdb is not supported with --mode hybrid\n");
582	    return 2;
583	  }
584	  // --verify re-runs the workload against a QEMU oracle -- only the hybrid
585	  // composition has a second engine to check.
586	  if (cli.verify && cli.model != "hybrid") {
587	    std::fprintf(stderr,
588	                 "andesim run: --verify requires --mode hybrid (the %s "
589	                 "model has nothing to cross-check)\n",
590	                 cli.model.c_str());
591	    return 2;
592	  }
593	  // Post-`--` args are forwarded verbatim to the engine -- but hybrid has TWO
594	  // legs (a QEMU fast-forward + a vsim measure leg) whose command lines the
595	  // handoff builds itself, so there is no single "the engine" to forward to.
596	  // Reject rather than silently drop (the old behavior) or guess a leg. vsim
597	  // options have dedicated flags (--kanata/--objdump); fast/cycle still forward.
598	  if (!cli.passthrough.empty() && cli.model == "hybrid") {
599	    std::fprintf(stderr,
600	                 "andesim run: --mode hybrid takes no `-- <args>` (the handoff "
601	                 "builds both legs' command lines; use --kanata/--objdump for "
602	                 "vsim options, or --mode fast|cycle to forward to one engine)\n");
603	    return 2;
604	  }
605	  // --trigger / --pc-start / --pc-end delimit the hybrid ROI window. --trigger
606	  // is hybrid-only; --pc-start/--pc-end belong to --trigger pc specifically. Any
607	  // other mode/trigger would SILENTLY drop them and hand back a figure for the
608	  // wrong window (fast/cycle: the whole program; hybrid+marker: the marker
609	  // window), so reject instead of measuring something the user did not ask for.
610	  if (!cli.trigger.empty() && cli.model != "hybrid") {
611	    std::fprintf(stderr,
612	                 "andesim run: --trigger applies only to --mode hybrid "
613	                 "(the ROI delimiter); fast/cycle run the whole program\n");
614	    return 2;
615	  }
616	  if (!cli.pc_end.empty() && cli.trigger != "pc") {
617	    std::fprintf(stderr,
618	                 "andesim run: --pc-end applies only to --mode hybrid "
619	                 "--trigger pc\n");
620	    return 2;
621	  }
622	  if (!cli.pc_start.empty() && cli.trigger != "pc") {
623	    std::fprintf(stderr,
624	                 "andesim run: --pc-start applies only to --mode hybrid "
625	                 "--trigger pc\n");
626	    return 2;
627	  }
628	  if (cli.model == "fast") return run_fast(cli);
629	  if (cli.model == "cycle") return run_accurate(cli);
630	  return run_hybrid(cli);  // model validated above; only hybrid remains
631	}
632	
633	}  // namespace andes_sim
