15	namespace andes_sim {
16	
17	// One role's argv template, e.g. role "accurate-leg" -> {"{bin}",
18	// "--resume-from-qemu", "{state_in}", ...}. {placeholders} are filled by the
19	// plan executor (F6).
20	struct EngineInvoke {
21	  std::string role;
22	  std::vector<std::string> argv;
23	};
24	
25	struct EngineDescriptor {
26	  std::string id;                       // "qemu", "verilator:ax45mpv_premium"
27	  std::string type;                     // qemu | verilator | alioth | sid
28	  std::string kind;                     // functional | cycle-accurate
29	  long vlen = 0;                        // RVV params; 0 = not reported
30	  long dlen = 0;
31	  long elen = 0;
32	  long xlen = 0;
33	  std::vector<std::string> triggers;    // marker | pc
34	  std::vector<std::string> roles;       // standalone | fast-leg | accurate-leg
35	  std::vector<std::string> state;       // resume | drain (hybrid_state_v1 caps)
36	  std::vector<std::string> andes_csrs;  // Andes CSRs this engine implements; the
37	                                        // --verify gate (empty = compare all)
38	  std::vector<EngineInvoke> invoke;     // argv template per role
39	  std::string result;                   // stderr:<re> | state.mcycle
40	
41	  // Filled by the registry, not present in the JSON:
42	  std::string bin_path;                 // resolved path to the binary
43	  std::string source;                   // built-in | --describe | sidecar
44	
45	  const std::vector<std::string>* invoke_for(std::string_view role) const {
46	    for (const EngineInvoke& iv : invoke)
47	      if (iv.role == role) return &iv.argv;
48	    return nullptr;
49	  }
50	};
