52	// Build a descriptor from parsed JSON. Returns "" on success or an error
53	// message naming the first problem (id and type are required).
54	inline std::string descriptor_from_json(const json::Value& v,
55	                                        EngineDescriptor& out) {
56	  if (!v.is_object()) return "descriptor is not a JSON object";
57	
58	  const json::Value* id = v.find("id");
59	  if (!id || !id->is_string() || id->str.empty()) return "missing string 'id'";
60	  out.id = id->as_string();
61	
62	  const json::Value* type = v.find("type");
63	  if (!type || !type->is_string()) return "missing string 'type'";
64	  out.type = type->as_string();
65	
66	  if (const json::Value* x = v.find("kind")) out.kind = x->as_string();
67	  if (const json::Value* x = v.find("vlen")) out.vlen = x->as_int();
68	  if (const json::Value* x = v.find("dlen")) out.dlen = x->as_int();
69	  if (const json::Value* x = v.find("elen")) out.elen = x->as_int();
70	  if (const json::Value* x = v.find("xlen")) out.xlen = x->as_int();
71	  if (const json::Value* x = v.find("triggers")) out.triggers = x->as_string_array();
72	  if (const json::Value* x = v.find("roles")) out.roles = x->as_string_array();
73	  if (const json::Value* x = v.find("state")) out.state = x->as_string_array();
74	  if (const json::Value* x = v.find("andes_csrs"))
75	    out.andes_csrs = x->as_string_array();
76	  if (const json::Value* x = v.find("result")) out.result = x->as_string();
77	
78	  if (const json::Value* inv = v.find("invoke"); inv && inv->is_object()) {
79	    for (size_t k = 0; k < inv->keys.size(); ++k)
80	      out.invoke.push_back({inv->keys[k], inv->vals[k].as_string_array()});
81	  }
82	  return "";
83	}
84	
85	}  // namespace andes_sim
