12	namespace andes_sim {
13	namespace {
14	
15	long now_ms() {
16	  struct timespec ts;
17	  clock_gettime(CLOCK_MONOTONIC, &ts);
18	  return ts.tv_sec * 1000L + ts.tv_nsec / 1000000L;
19	}
20	
21	// In the just-forked child: replace the image with argv (argv[0] resolved via
22	// PATH), or _exit(127) if exec fails. Never returns.
23	[[noreturn]] void exec_or_die(const std::vector<std::string>& argv) {
24	  std::vector<char*> cargv;
25	  cargv.reserve(argv.size() + 1);
26	  for (const std::string& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
27	  cargv.push_back(nullptr);
28	  execvp(cargv[0], cargv.data());
29	  _exit(127);  // exec failed
30	}
31	
32	// Reap `pid` and map its wait status to an exit code: the child's exit code,
33	// 128+signal if it was signalled, or -1 otherwise.
34	int wait_for_exit_code(pid_t pid) {
35	  int status = 0;
36	  waitpid(pid, &status, 0);
37	  if (WIFEXITED(status)) return WEXITSTATUS(status);
38	  if (WIFSIGNALED(status)) return 128 + WTERMSIG(status);
39	  return -1;
40	}
41	
42	// fork + (optional chdir) + (optional stdin from /dev/null) + exec.
43	// When `wait` is true (the default) waits for the child and returns its exit
44	// code, 128+signal if signalled, or -1 on failure. When `wait` is false
45	// returns the child pid immediately without waiting (caller owns the child).
46	// Backs run_inherit (build: stdin closed, chdir), exec_passthrough (run
47	// fast/cycle: stdin inherited, no chdir), and fork_background (no wait).
48	int spawn_inherit(const std::vector<std::string>& argv, const std::string& cwd,
49	                  bool stdin_from_devnull, bool wait = true) {
50	  if (argv.empty()) return -1;
51	
52	  pid_t pid = fork();
53	  if (pid < 0) return -1;
54	
55	  if (pid == 0) {  // child
56	    if (!cwd.empty() && chdir(cwd.c_str()) != 0) _exit(127);
57	    if (stdin_from_devnull) {
58	      int devnull = open("/dev/null", O_RDONLY);
59	      if (devnull >= 0) {
60	        dup2(devnull, STDIN_FILENO);
61	        if (devnull > 2) close(devnull);
62	      }
63	    }
64	    exec_or_die(argv);
65	  }
66	
67	  if (!wait) return static_cast<int>(pid);
68	  return wait_for_exit_code(pid);
69	}
70	
71	}  // namespace
72	
73	RunResult run_process(const std::vector<std::string>& argv, int timeout_ms) {
74	  RunResult r;
75	  if (argv.empty()) {
76	    r.spawn_failed = true;
77	    return r;
78	  }
79	
80	  int fds[2];
81	  if (pipe(fds) != 0) {
82	    r.spawn_failed = true;
83	    return r;
84	  }
85	
86	  pid_t pid = fork();
87	  if (pid < 0) {
88	    close(fds[0]);
89	    close(fds[1]);
90	    r.spawn_failed = true;
91	    return r;
92	  }
93	
94	  if (pid == 0) {  // child
95	    close(fds[0]);
96	    dup2(fds[1], STDOUT_FILENO);
97	    int devnull = open("/dev/null", O_RDWR);
98	    if (devnull >= 0) {
99	      dup2(devnull, STDIN_FILENO);
100	      dup2(devnull, STDERR_FILENO);
101	      if (devnull > 2) close(devnull);
102	    }
103	    close(fds[1]);
104	    exec_or_die(argv);
105	  }
106	
107	  // parent
108	  close(fds[1]);
109	  int rfd = fds[0];
110	  const long deadline = now_ms() + timeout_ms;
111	  char buf[4096];
112	
113	  while (true) {
114	    long remaining = deadline - now_ms();
115	    if (remaining < 0) remaining = 0;
116	    struct pollfd pfd{rfd, POLLIN, 0};
117	    int pr = poll(&pfd, 1, static_cast<int>(remaining));
118	    if (pr < 0) {
119	      if (errno == EINTR) continue;
120	      break;
121	    }
122	    if (pr == 0) {  // timed out with no data ready
123	      kill(pid, SIGKILL);
124	      r.timed_out = true;
125	      break;
126	    }
127	    if (pfd.revents & (POLLIN | POLLHUP | POLLERR)) {
128	      ssize_t n = read(rfd, buf, sizeof(buf));
129	      if (n > 0) {
130	        r.out.append(buf, static_cast<size_t>(n));
131	      } else if (n == 0) {
132	        break;  // EOF: child closed stdout
133	      } else {
134	        if (errno == EINTR) continue;
135	        break;
136	      }
137	    }
138	    if (now_ms() >= deadline) {  // chatty child kept us past the deadline
139	      kill(pid, SIGKILL);
140	      r.timed_out = true;
141	      break;
142	    }
143	  }
144	
145	  close(rfd);
146	  int status = 0;
147	  waitpid(pid, &status, 0);
148	  // rc stays -1 (the default) when timed out or abnormally terminated.
149	  if (!r.timed_out && WIFEXITED(status)) r.rc = WEXITSTATUS(status);
150	  return r;
151	}
152	
153	int run_inherit(const std::vector<std::string>& argv, const std::string& cwd) {
154	  return spawn_inherit(argv, cwd, /*stdin_from_devnull=*/true);
155	}
156	
157	int exec_passthrough(const std::vector<std::string>& argv) {
158	  return spawn_inherit(argv, /*cwd=*/"", /*stdin_from_devnull=*/false);
159	}
160	
161	int fork_background(const std::vector<std::string>& argv) {
162	  return spawn_inherit(argv, /*cwd=*/"", /*stdin_from_devnull=*/false, /*wait=*/false);
163	}
164	
165	namespace {
166	
167	// Drain everything readable on `fd` into `buf`, delivering each completed
168	// '\n'-terminated line (newline stripped) to on_line. Returns false at EOF /
169	// error so the caller stops polling that stream.
170	bool pump_stream(int fd, int stream, std::string& buf,
171	                 const std::function<void(int, std::string_view)>& on_line) {
172	  char rb[4096];
173	  const ssize_t n = read(fd, rb, sizeof rb);
174	  if (n == 0) return false;          // EOF: child closed this stream
175	  if (n < 0) return errno == EINTR;  // transient -> keep; real error -> stop
176	  buf.append(rb, static_cast<size_t>(n));
177	  size_t nl;
178	  while ((nl = buf.find('\n')) != std::string::npos) {
179	    on_line(stream, std::string_view(buf.data(), nl));
180	    buf.erase(0, nl + 1);
181	  }
182	  return true;
183	}
184	
185	}  // namespace
186	
187	int run_line_filtered(
188	    const std::vector<std::string>& argv,
189	    const std::function<void(int, std::string_view)>& on_line) {
190	  if (argv.empty()) return -1;
191	
192	  int out_fds[2], err_fds[2];
193	  if (pipe(out_fds) != 0) return -1;
194	  if (pipe(err_fds) != 0) {
195	    close(out_fds[0]);
196	    close(out_fds[1]);
197	    return -1;
198	  }
199	
200	  pid_t pid = fork();
201	  if (pid < 0) {
202	    close(out_fds[0]);
203	    close(out_fds[1]);
204	    close(err_fds[0]);
205	    close(err_fds[1]);
206	    return -1;
207	  }
208	
209	  if (pid == 0) {  // child: stdout/stderr to the pipes, stdin inherited
210	    close(out_fds[0]);
211	    close(err_fds[0]);
212	    dup2(out_fds[1], STDOUT_FILENO);
213	    dup2(err_fds[1], STDERR_FILENO);
214	    if (out_fds[1] > 2) close(out_fds[1]);
215	    if (err_fds[1] > 2) close(err_fds[1]);
216	    exec_or_die(argv);
