289	    CHECK(!err.empty());
290	    leg_trigger_args({"pc", {}}, "fast-leg", err);
291	    CHECK(!err.empty());
292	
293	    // verify oracle leg (verify_oracle F4): qemu drains at the ROI exit,
294	    // sampling at vsim's drained pc (drain_pc).
295	    const Trigger vm = {"verify-marker", {{"drain_pc", "0x100072"}}};
296	    LegTriggerArgs vmf = leg_trigger_args(vm, "fast-leg", err);
297	    CHECK(err.empty());
298	    CHECK(vmf.plugin_suffix == ",exit_marker=1,drain_pc=0x100072");
299	    CHECK(vmf.extra.empty());
300	    const Trigger vp = {"verify-pc",
301	                        {{"exit_pc", "0x20"}, {"drain_pc", "0x28"}}};
302	    LegTriggerArgs vpf = leg_trigger_args(vp, "fast-leg", err);
303	    CHECK(err.empty());
304	    CHECK(vpf.plugin_suffix == ",exit_pc=0x20,drain_pc=0x28");
305	    leg_trigger_args({"verify-marker", {}}, "fast-leg", err);
306	    CHECK(!err.empty());  // missing drain_pc
307	    leg_trigger_args({"verify-pc", {{"drain_pc", "0x28"}}}, "fast-leg", err);
308	    CHECK(!err.empty());  // missing exit_pc
309	  }
310	
311	  // --- plan_argvs: pc trigger threads enter_pc (qemu) + exit_pc (vsim) ---
312	  {
313	    Plan p = plan;
314	    const Trigger pc = {"pc", {{"enter_pc", "0x100000"}, {"exit_pc", "0x100042"}}};
315	    p.steps[0].trigger = pc;
316	    p.steps[1].trigger = pc;
317	    std::string err;
318	    std::vector<std::vector<std::string>> argvs =
319	        plan_argvs(p, engines, "/wd", rc, err);
320	    CHECK(err.empty());
321	    CHECK(argvs.size() == 2);
322	    if (argvs.size() == 2) {
323	      // qemu: enter_pc folded into the single -plugin token (its last arg)
324	      CHECK(argvs[0].back() == "/pl,outfile=/wd/state-0.bin,enter_pc=0x100000");
325	      // vsim: --hybrid-exit-pc appended verbatim after the filled template
326	      check_eq(argvs[1],
327	               {"/vbin", "/e", "--resume-from-qemu", "/wd/state-0.bin",
328	                "--handoff-out", "/wd/state-1.bin", "--shared-mem-path", "/mm",
329	                "--shared-mem-size", "134217728", "--shared-mem-base", "0x0",
330	                "--hybrid-exit-pc", "0x100042"},
331	               "pc-step1");
332	    }
333	  }
334	
335	  // --- plan_argvs: Step.extra_args append AFTER trigger args (e2e.sh order) ---
336	  {
337	    Plan p = plan;
338	    const Trigger pc = {"pc", {{"enter_pc", "0x100000"}, {"exit_pc", "0x100042"}}};
339	    p.steps[0].trigger = pc;
340	    p.steps[1].trigger = pc;
341	    p.steps[1].extra_args = {"--kanata", "k.txt"};
342	    std::string err;
343	    std::vector<std::vector<std::string>> argvs =
344	        plan_argvs(p, engines, "/wd", rc, err);
345	    CHECK(err.empty());
346	    if (argvs.size() == 2) {
347	      const std::vector<std::string>& v = argvs[1];
348	      CHECK(v.size() >= 4);
349	      // tail order: ... --hybrid-exit-pc 0x100042 --kanata k.txt
350	      CHECK(v[v.size() - 4] == "--hybrid-exit-pc");
351	      CHECK(v[v.size() - 3] == "0x100042");
352	      CHECK(v[v.size() - 2] == "--kanata");
353	      CHECK(v.back() == "k.txt");
354	    }
355	  }
356	
357	  // unknown engine id is an error
358	  {
359	    Plan bad = plan;
360	    bad.steps[0].engine_id = "nope";
361	    std::string err;
362	    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
363	    CHECK(!err.empty());
364	  }
365	  // a role the engine has no template for is an error
366	  {
367	    Plan bad = plan;
368	    bad.steps[1].role = "no-such-role";
369	    std::string err;
370	    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
371	    CHECK(!err.empty());
372	  }
373	
374	  // plan_step_rc_error: a drain leg that exits 0 ran the workload to completion
375	  // without ever reaching its ROI boundary -- the trigger never fired. The
376	  // message must say so and name the trigger kind, not just the bare
377	  // "expected exit 200, got 0" the user cannot act on.
378	  {
379	    const Step s{"qemu", "fast-leg", {"marker", {}}};
380	    const std::string m = plan_step_rc_error(0, s, 200, 0);
381	    CHECK(m.find("plan step 0") != std::string::npos);
382	    CHECK(m.find("marker") != std::string::npos);
383	    CHECK(m.find("without reaching") != std::string::npos);
384	  }
385	  // a genuine non-zero failure (engine crash, not a clean completion) keeps the
386	  // bare line -- no false "trigger never fired" claim.
387	  {
388	    const Step s{"qemu", "fast-leg", {"marker", {}}};
389	    const std::string m = plan_step_rc_error(1, s, 200, 139);
390	    CHECK(m.find("expected exit 200, got 139") != std::string::npos);
391	    CHECK(m.find("without reaching") == std::string::npos);
392	  }
393	
394	  return andes_sim::test::report("plan");
395	}
